  ('photosynthesis', 'fotossíntese', 'The process by which green plants and some other organisms use sunlight to synthesize nutrients from carbon dioxide and water, producing oxygen as a byproduct.', 'Photosynthesis is essential for life on Earth as it produces oxygen.', 'B2', 'noun', 'science', 36156),
  ('cataclysm', 'cataclismo', 'A sudden and violent physical change in the Earth''s crust, such as an earthquake or volcanic eruption.', 'The ancient city was destroyed by a volcanic cataclysm.', 'C1', 'noun', 'general-vocabulary', 36160),
  ('sportsmanship', 'espírito esportivo', 'The quality of behaving fairly, respectfully, and with integrity while participating in sports or competitive activities.', 'He showed great sportsmanship by helping his opponent up after a fall.', 'B1', 'noun', 'sports', 36171),
  ('teardrop', 'lágrima', 'A single drop of the clear, salty liquid that is secreted by the lacrimal glands, typically as a result of emotion or irritation.', 'A single teardrop rolled down her cheek.', 'A2', 'noun', 'general-vocabulary', 36178),
