  ('bad-tempered', 'mal-humorado', 'Tending to become angry or annoyed quickly; having a difficult or unpleasant mood.', 'He was bad-tempered all morning because he didn''t sleep well.', 'B2', 'adjective', 'general-vocabulary', 36311),
