  ('happy-go-lucky', 'despreocupado', 'Having a cheerful and carefree attitude, not worrying about the future or consequences.', 'She has a happy-go-lucky personality that makes everyone smile.', 'B2', 'adjective', 'general-vocabulary', 38426),
  ('adrenal', 'adrenal', 'Of or pertaining to the pair of endocrine glands located near the kidneys, which produce hormones like adrenaline and cortisol.', 'The adrenal glands release cortisol in response to stress.', 'B2', 'adjective', 'health', 38430),
