  ('mastodon', 'mastodonte', 'A large, extinct elephant-like animal that lived from the Miocene through the Pleistocene epochs; distinguished from mammoths by the structure of its molar teeth.', 'Scientists unearthed a nearly complete skeleton of a mastodon in North America.', 'B2', 'noun', 'science', 38528),
  ('shrunken', 'encolhido', 'Describes something that has become smaller, leaner, and wrinkled, often due to age, illness, or lack of moisture.', 'The old man''s shrunken hands showed signs of arthritis.', 'B2', 'adjective', 'general-vocabulary', 38529),
  ('acacia', 'acácia', 'Any of various trees or shrubs belonging to the genus Acacia, often with feathery leaves and clusters of yellow or white flowers.', 'The acacia tree provided shade in the hot savanna.', 'B2', 'noun', 'science', 38534),
