  ('strangles', 'garrotilho', 'An acute, highly contagious bacterial infection of horses and other equids, characterized by inflammation and abscessation of the upper respiratory tract and lymph nodes.', 'The veterinarian diagnosed the foal with strangles after noticing the swollen lymph nodes.', 'C1', 'noun', 'health', 38546),
  ('overlay', 'revestir', 'To put a layer of something over the surface of something else.', 'The designer decided to overlay a transparent image onto the background.', 'C2', 'verb', 'general-vocabulary', 38559),
