  ('ingrained', 'enraizado', 'Firmly fixed or established, especially of habits, beliefs, or attitudes.', 'Her ingrained habit of checking her phone every few minutes was hard to break.', 'C1', 'adjective', 'general-vocabulary', 38770),
  ('ephemeral', 'efêmero', 'Lasting for a very short time; fleeting.', 'The beauty of cherry blossoms is ephemeral.', 'C2', 'adjective', 'general-vocabulary', 38773),
