  ('recompense', 'compensar', 'To provide payment or make amends for damage, loss, or injury suffered.', 'The company recompensed the workers for their overtime.', 'C1', 'verb', 'general-vocabulary', 38891),
  ('acquaint', 'familiarizar', 'To inform or make someone familiar with a fact, situation, or subject.', 'The manager acquainted the new employees with the company policies.', 'B2', 'verb', 'general-vocabulary', 38892),
  ('ambivalent', 'ambivalente', 'Having contradictory feelings or attitudes about someone or something.', 'She felt ambivalent about moving to a new city.', 'B2', 'adjective', 'general-vocabulary', 38901),
  ('malnourished', 'desnutrido', 'In a state of poor health due to not receiving enough food or the right kinds of food.', 'The doctor treated many malnourished children in the refugee camp.', 'B2', 'adjective', 'health', 38904),
