  ('sporadic', 'esporádico', 'Happening at irregular intervals or in scattered instances.', 'The region experienced sporadic rainfall throughout the year.', 'B2', 'adjective', 'general-vocabulary', 38934),
  ('asystole', 'assistolia', 'The absence of systole; failure of the heart''s ventricles to contract, often due to ventricular fibrillation, resulting in no heartbeat and leading to oxygen deprivation and eventual death.', 'The patient was diagnosed with asystole after the cardiac monitor showed a flat line.', 'C2', 'noun', 'health', 38937),
  ('anorexia', 'anorexia', 'A serious medical condition characterized by an abnormally low body weight, an intense fear of gaining weight, and a distorted perception of body weight, often leading to self-starvation.', 'She was diagnosed with anorexia and is now receiving treatment.', 'B2', 'noun', 'health', 38940),
  ('combustible', 'combustível', 'Able to catch fire and burn easily.', 'Gasoline is a highly combustible liquid.', 'B2', 'adjective', 'science', 38962),
