  ('fungal', 'fúngico', 'Of, relating to, or caused by fungi, which are organisms such as molds, mushrooms, and yeasts.', 'The patient was diagnosed with a fungal infection on his skin.', 'B2', 'adjective', 'science', 38981),
  ('slither', 'rastejar', 'To move in a smooth, quiet, and often secretive manner, like a snake.', 'The cat slithered through the narrow gap in the fence.', 'C2', 'verb', 'general-vocabulary', 38988),
  ('conformity', 'conformidade', 'The state of being similar or identical in form, nature, or character.', 'There is a striking conformity between the two paintings.', 'C1', 'noun', 'general-vocabulary', 38991),
  ('workday', 'dia útil', 'A day on which work is typically done, as opposed to a weekend or holiday.', 'Monday is a workday for most people.', 'A2', 'noun', 'general-vocabulary', 38992),
  ('turncoat', 'vira-casaca', 'A person who switches sides or abandons their principles, party, or friends, often for personal gain.', 'The politician was labeled a turncoat after joining the opposing party.', 'C1', 'noun', 'general-vocabulary', 38993),
  ('patriarchal', 'patriarcal', 'Relating to a social system where men hold primary power and authority, especially in family and political structures.', 'The patriarchal structure of the society limited women''s rights.', 'B2', 'adjective', 'general-vocabulary', 38999),
  ('fallback', 'plano B', 'A plan or option that can be used if the original plan fails.', 'We have a fallback in case the funding falls through.', 'B2', 'noun', 'general-vocabulary', 39000),
  ('warlike', 'beligerante', 'Having a tendency or readiness to engage in war or conflict; favoring a hard-line or combative approach.', 'The warlike rhetoric of the general alarmed the diplomats.', 'B2', 'adjective', 'politics', 39001),
  ('contour', 'contorno', 'The outline of a figure, body, or mass, especially as seen from a particular angle.', 'The artist carefully drew the contour of the model''s face.', 'B2', 'noun', 'general-vocabulary', 39003),
