  ('visibly', 'visivelmente', 'In a manner that is noticeable or apparent to the eye.', 'She was visibly upset after hearing the news.', 'B2', 'adverb', 'general-vocabulary', 39039),
  ('juicer', 'espremedor', 'A device used to extract juice from fruits and vegetables.', 'She used an electric juicer to make fresh orange juice.', 'A2', 'noun', 'general-vocabulary', 39040),
  ('theorist', 'teórico', 'An individual who formulates or studies theories, especially in scientific or artistic fields.', 'The theorist proposed a new model for quantum mechanics.', 'B2', 'noun', 'general-vocabulary', 39045),
