  ('pontoon', 'pontão', 'A flat-bottomed boat or floating platform used as a dock, bridge support, or temporary structure on water.', 'The army built a pontoon bridge to cross the river.', 'B2', 'noun', 'general-vocabulary', 40899),
  ('palatable', 'gostoso', 'Having a pleasant or acceptable taste.', 'The chef made the dish more palatable with fresh herbs.', 'C2', 'adjective', 'food', 40905),
  ('diction', 'dicção', 'The style of speaking or pronouncing words, especially in terms of clarity and distinctness.', 'The actor''s diction was so clear that everyone understood every word.', 'B2', 'noun', 'general-vocabulary', 40907),
  ('pessimism', 'pessimismo', 'A tendency to see the worst aspect of things or believe that the worst will happen.', 'His constant pessimism made it hard to work with him.', 'B2', 'noun', 'general-vocabulary', 40908),
