  ('consecrate', 'consagrar', 'To declare something sacred or dedicate it to a religious purpose.', 'The bishop consecrated the new church last Sunday.', 'C1', 'verb', 'general-vocabulary', 41220),
  ('assimilation', 'assimilação', 'The process by which individuals or groups from different backgrounds adopt the customs and attitudes of a dominant culture, often seeing themselves as part of a larger national community.', 'The immigrant community underwent a gradual assimilation into the local culture.', 'C2', 'noun', 'general-vocabulary', 41221),
