  ('autobiographical', 'autobiográfico', 'Describing or characteristic of a person''s own written account of their life.', 'Her novel is highly autobiographical, drawing from her childhood experiences.', 'B2', 'adjective', 'general-vocabulary', 41257),
  ('durian', 'durião', 'A large tree native to Southeast Asia that produces an edible fruit with a hard, spiny rind.', 'The durian tree can grow up to 50 meters tall in tropical climates.', 'B1', 'noun', 'general-vocabulary', 41272),
