  ('monastic', 'monacal', 'Relating to the secluded communal life of monks or nuns, typically under religious vows and separated from worldly affairs.', 'He chose a monastic lifestyle, living in a remote abbey.', 'C2', 'adjective', 'general-vocabulary', 41282),
  ('silica', 'sílica', 'A white or colorless, hard, vitreous, insoluble solid (SiO2) that occurs widely in the earth''s crust as quartz, cristobalite, tridymite, or lechatelierite.', 'Silica is a major component of sand and many types of rocks.', 'C1', 'noun', 'science', 41291),
  ('oxytocin', 'ocitocina', 'A hormone produced in the hypothalamus and released by the pituitary gland, which plays a key role in childbirth, lactation, and social bonding.', 'Oxytocin is often called the ''love hormone'' because it is released during hugging and bonding.', 'C1', 'noun', 'health', 41297),
